// Un resumen por persona con sus solicitudes abiertas que llevan DIAS días o más sin cambios. Las que
// no tienen responsable van a todos los administradores. Una solicitud no se vuelve a recordar hasta
// que pasen otros DIAS días: 'Recordatorios recientes' trae los ya enviados.
const DIAS = 3; // Espejo de dias_recordatorio() en la base. Las consultas de arriba usan el mismo valor.
const app = $env.APP_URL.replace(/\/$/, '');
const ahora = Date.now();

const solicitudes = $('Buscar estancadas').all().map((item) => item.json).filter((s) => s.id);
const personal = $('Buscar personal').all().map((item) => item.json).filter((p) => p.id && p.correo);
const recordadas = new Set($('Recordatorios recientes').all().map((item) => item.json.solicitud_id).filter(Boolean));
const porId = new Map(personal.map((p) => [p.id, p]));
const admins = personal.filter((p) => p.rol === 'admin');

// Espejo de ETIQUETA_ESTADO (web/src/lib/dominio.ts); solo los estados abiertos.
const ESTADOS = { pendiente: 'Pendiente', en_proceso: 'En proceso' };
const esc = (texto) => String(texto ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
// Mismo cálculo que dias_sin_cambio en la vista solicitudes_estancadas.
const diasSinCambio = (s) => Math.floor((ahora - new Date(s.actualizada).getTime()) / 86400000);

const resumenes = new Map();
for (const solicitud of solicitudes) {
  if (recordadas.has(solicitud.id)) continue;
  const responsable = porId.get(solicitud.responsable_id);
  for (const persona of responsable ? [responsable] : admins) {
    if (!resumenes.has(persona.id)) resumenes.set(persona.id, { persona, casos: [] });
    resumenes.get(persona.id).casos.push({ ...solicitud, libre: !responsable });
  }
}

return [...resumenes.values()].map(({ persona, casos }) => {
  casos.sort((a, b) => diasSinCambio(b) - diasSinCambio(a));
  const n = casos.length;
  const filas = casos.map((c) =>
    `  <li><a href="${app}/gestion/solicitudes/${c.id}">${esc(c.asunto)}</a> · ${esc(ESTADOS[c.estado] ?? c.estado)} · ${diasSinCambio(c)} días sin cambios${c.libre ? ' · <strong>sin responsable</strong>' : ''}</li>`
  ).join('\n');
  return {
    json: {
      // Un correo cubre varias solicitudes: Enviar-aviso registra una fila por cada una.
      solicitud_id: null,
      solicitud_ids: casos.map((c) => c.id),
      tipo_aviso: 'recordatorio',
      destinatario: persona.correo,
      asunto: `Recordatorio: ${n === 1 ? '1 solicitud lleva' : `${n} solicitudes llevan`} ${DIAS} días o más sin cambios - Gestión de Solicitudes`,
      cuerpo: `<h2>Solicitudes sin movimiento</h2>
<p>Hola ${esc(persona.nombre)},</p>
<p>${n === 1 ? 'Esta solicitud lleva' : 'Estas solicitudes llevan'} ${DIAS} días o más sin cambios:</p>
<ul>
${filas}
</ul>
<p><a href="${app}/gestion">Abrir la bandeja</a></p>`,
    },
  };
});
